38	// The walled homeworld spends a login on the sibling that holds nothing rather than on growing the wall it
39	// already has. The colony is planted first so the sibling is bare from the moment the wall stands.
40	test('a walled homeworld reaches its naked colony with a wall order', function (): void {
41	    $situation = Situation::of($this)
42	        ->levelEveryPlanet('robot_factory', 2)
43	        ->levelEveryPlanet('shipyard', 4)
44	        ->levelEveryPlanet('solar_plant', 30)
