 16	// The merged QUAL-003 situation (invariant:NAKED_BESIDE_WALLED, aspect:shipyard). The cohort read found accounts
 17	// with planets at zero defence while a sibling held a real wall: the whole wall was raised on the planet
 18	// with the most to lose and the bare siblings were never reached. One login has to give the bare planet
 19	// the wall order the account already holds elsewhere, in the host's own yard.
 20	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
 21	    $situation = Situation::of($this)
 22	        ->levelEveryPlanet('robot_factory', 2)
 23	        ->levelEveryPlanet('shipyard', 4)
 24	        ->defence('rocket_launcher', 20)
 25	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
 26	        ->session();
 27	
 28	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
 29	        ->whereKeyNot($this->currentPlanetId)->value('id');
 30	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
 31	
 32	    $situation->expectWork(AiWorkKind::QueueUnits);
 33	
 34	    // A short build may already be complete by the time the session's own clock has advanced to every
 35	    // intent, so the wall counts whether it is standing or still paid for in the yard.
 36	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
 37	});
 38	
 39	// The bound on the other side: a planet that already holds a wall is not the account's next wall order,
 40	// so one login serves the bare sibling instead of stacking yet another batch on the walled planet.
 41	test('a login does not spend its wall order on the planet that already holds one', function (): void {
 42	    $situation = Situation::of($this)
 43	        ->levelEveryPlanet('robot_factory', 2)
 44	        ->levelEveryPlanet('shipyard', 4)
 45	        ->defence('rocket_launcher', 20)
 46	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
 47	        ->session();
 48	
 49	    $home = app(PlanetServiceFactory::class)->make($this->currentPlanetId, true);
 50	    $situation->expectWork(AiWorkKind::QueueUnits);
 51	
 52	    expect(app(DefenseNeedEvaluator::class)->standingUnits($home))->toBe(20, 'expected the walled planet untouched while its sibling is bare; ' . $situation->account());
 53	});
 54	
 55	// The invariant counts the account, not the planet (player 51: one planet holding 1,496 units, others
 56	// naked), so a full day of the account's own logins must leave no sibling at zero defence.
 57	test('an account whose homeworld holds a wall leaves no sibling naked', function (): void {
 58	    $situation = Situation::of($this)
 59	        ->resources(50_000_000, 50_000_000, 50_000_000)
 60	        ->level('robot_factory', 2)
 61	        ->level('shipyard', 4)
 62	        ->ships('small_cargo', 10)
 63	        ->ships('light_laser', 60)
 64	        ->colony()
 65	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
 66	
 67	    $situation->day();
 68	
 69	    expect(nakedPlanets($this->currentUserId))->toBe([], 'these planets stay at zero defence; ' . $situation->account());
 70	});
 71	
 72	// A walled homeworld moves the bare sibling before the sibling's own habits, so one login already
 73	// turns to the yard the sibling needs rather than leaving it for a later day. The sibling's yard is
 74	// below the wall's unit, so the order it takes is the facility the wall waits on.
 75	test('a login beside a walled homeworld turns to the bare sibling', function (): void {
 76	    $situation = Situation::of($this)
 77	        ->resources(50_000_000, 50_000_000, 50_000_000)
 78	        ->level('robot_factory', 2)
 79	        ->level('shipyard', 4)
 80	        ->ships('small_cargo', 10)
 81	        ->ships('light_laser', 60)
 82	        ->colony()
 83	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
 84	
 85	    $situation->session();
 86	
 87	    foreach (nakedPlanets($this->currentUserId) as $planetId) {
 88	        $ordered = BuildingQueue::query()->where('planet_id', $planetId)->where('canceled', 0)->exists();
 89	        expect($ordered)->toBeTrue('the bare sibling got no order this login; ' . $situation->account());
 90	    }
 91	});
