108	// The bound at zero: with nothing to build with, the account queues no wall at all -- the host's own
109	// affordability gate is not bypassed to make a naked planet look walled.
110	test('an account that can pay for nothing queues no wall', function (): void {
111	    $situation = Situation::of($this)
112	        ->level('robot_factory', 2)
113	        ->level('shipyard', 4)
114	        ->ships('small_cargo', 10)
115	        ->ships('light_laser', 60)
116	        ->colony();
117	
118	    $situation->session();
119	
120	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
121	
122	    expect($situation->work())->not->toBeEmpty()
123	        ->and(array_intersect($defence, $situation->queued()))->toBe([], 'a wall was queued without the resources to pay for it; ' . $situation->account());
124	});
