11	uses(IsolatedAccountTestCase::class);
12	
13	// PERS-004: what a planet stands to lose is not only the output that piles up while the account is
14	// away. A fleet left standing in orbit and the solar satellites a planet keeps for power are worth to
15	// a raider exactly what the pile is, so a wall sized on production alone leaves them uncovered. The
16	// kit plants the idle fleet on a planet whose small wall already covers the mines, and the evaluator
17	// must state a need only once the fleet is there.
18	
19	test('an idle fleet raises what the planet stands to lose', function (): void {
20	    $situation = Situation::of($this)
21	        ->resources(1_000_000, 1_000_000, 1_000_000)
22	        ->level('shipyard', 4)
23	        ->ships('rocket_launcher', 200);
24	
25	    $player = $this->planetService->getPlayer();
26	    $covered = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
27	
28	    expect($covered)->toBeNull('the wall already covers production-only exposure; ' . $situation->account());
29	
30	    $situation->ships('light_fighter', 2_000);
31	
32	    $exposed = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
33	
34	    expect($exposed)->toBeInstanceOf(DefenseNeed::class)
35	        ->and($exposed->protectedValue)->toBeGreaterThan(0.0)
36	        ->and($exposed->currentDefenseValue)->toBeGreaterThan(0.0);
37	});
38	
39	// The zero case of the rule: the fleet only adds to the exposure, it is not what creates the need. A
40	// planet whose own output is nothing still takes the file's floor, so an account is not left naked
41	// because it has no fleet to protect.
42	test('a planet with nothing standing in orbit still takes the doctrine floor', function (): void {
43	    resolve(SettingsService::class)->set('economy_speed', 1);
44	
45	    Situation::of($this)
46	        ->resources(1_000_000, 1_000_000, 1_000_000)
47	        ->level('shipyard', 4)
48	        ->level('metal_mine', 0)
49	        ->level('crystal_mine', 0)
50	        ->level('deuterium_synthesizer', 0);
51	
52	    $this->planetService->updateResourceProductionStats();
53	
54	    $need = app(DefenseNeedEvaluator::class)->evaluate($this->planetService->getPlayer(), $this->planetService);
55	
56	    expect($need)->toBeInstanceOf(DefenseNeed::class)
57	        ->and($need->reason)->toBe('defense:need:minimum-deterrent');
58	});
59	
60	// The bound: a fleet standing on a planet that already holds the wall the behaviour file caps adds
61	// nothing, because the ceiling ends the need before exposure is weighed at all.
62	test('a fleet on a planet at the wall ceiling wants no further wall', function (): void {
63	    Situation::of($this)
64	        ->resources(50_000_000, 50_000_000, 50_000_000)
65	        ->ships('light_fighter', 2_000)
66	        ->ships('rocket_launcher', 20_000);
67	
68	    expect(app(DefenseNeedEvaluator::class)->evaluate($this->planetService->getPlayer(), $this->planetService))->toBeNull();
69	});
